```
class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        def hours(speed):
            return sum((p + speed - 1) // speed for p in piles)

        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            if hours(mid) <= h:
                hi = mid
            else:
                lo = mid + 1
        return lo
```

